// === Tab: mySketch ===
// #WCCChallenge Topic: Petri Dish

let particles = [];
let centerPos;
let centerStr = 0.001; //center strength
let attStr = 24 //attraction strength
let repStr = 50; //repulsion strength
let maxVel = 36;
let radius = 24;
let num=201;
let d=500;

function setup() {
  createCanvas(windowWidth, windowHeight);
  //colorMode(HSB);

  centerPos = createVector(width / 2, height / 2);

  for (let i = 0; i < num; i++) {
    let x = random(width);
    let y = random(height);
    particles.push(new Particle(x, y, radius));
  }
}

function draw() {
  background("#FFBD60");

	//stroke(0);
	fill("#4A4949");
	circle(width/2,height/2,d+20);
	fill("#000000");
	circle(width/2,height/2,d);

  for (let p of particles) {
    for (let target of particles) {
      if (p != target) {
        p.updateForce(target);
      }
    }
    p.acc.add(p.pos.copy().sub(centerPos).mult(-centerStr));
    p.update();
		//p.show();

		if (p.pos.dist(centerPos) < d/2-30) {
			p.show();
		}
  }
}

function mouseDragged() {
  for (let p of particles) {
    p.updateMouse();
  }
}


class Particle {
  constructor(x, y, r) {
    this.pos = createVector(x, y);
    this.vel = createVector();
    this.acc = createVector();
    this.r = r;
    this.aStr = attStr ;
    this.rStr = repStr ;
    this.col = "#B663F7";
  }

  show() {
    fill(this.col);
    noStroke();
    ellipse(this.pos.x, this.pos.y, this.r * 2);
  }

  update() {
    this.vel.add(this.acc);
    this.acc.mult(0);
    if (this.vel.mag() > maxVel) this.vel.setMag(maxVel);
    this.pos.add(this.vel);

    this.vel.mult(0.92);

		//color and size based on distance to center
    let dist = centerPos.dist(this.pos);
    this.r = map(dist, 0, 165, radius, 0);
		let c1=map(dist, 0, 165, 100, 80);
		let c2 = map(dist, 0, 165, 200, 100);
    this.col = color(234,c1,c2);

  }

  updateForce(target) {
    let force = p5.Vector.sub(target.pos, this.pos);
    let d = force.mag();
    force.normalize();

    if (d > 0.5) {
      if (d <= this.r * 16) {
        let attForce = force.copy().mult(this.aStr / (d * d)); 
        this.acc.add(attForce);
      }
      if (d <= this.r * 32) {
        let repForce = force.copy().mult(-this.rStr / (d * d));
        this.acc.add(repForce);
      }
      if (d < (this.r*1.5 + target.r)) {
        let overlapForce = force.copy().mult(d - (this.r*1.5 + target.r));
        this.vel.add(overlapForce.copy().mult(0.5));
        target.vel.add(overlapForce.mult(-0.5));
      }
    }
  }

  updateMouse() {
    let mousePos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let force = p5.Vector.sub(mousePos, this.pos);
    let d = force.mag();
    force.normalize();

    if(d<maxVel*2) {
      let repForce = force.copy().mult(-1);
      this.acc.add(repForce);
    }
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
